// ---------- jazyk rozhrania podľa prehliadača ----------
// Zdrojové texty sú po slovensky. Pre iný jazyk prehliadača sa texty v stránke preložia slovníkom nižšie,
// aj tie, ktoré aplikácia zmení počas behu (MutationObserver). Čeština a angličtina; iné jazyky dostanú angličtinu.
// Poradie: ?lang=… v adrese, potom voľba v Nastaveniach (uložená v prehliadači), potom jazyk prehliadača.
const UI_LANGS = { sk: "Slovenčina", cs: "Čeština", en: "English", es: "Español", ar: "العربية", tr: "Türkçe", hi: "हिन्दी", pl: "Polski", zh: "中文" };
let savedLang = null; try { savedLang = localStorage.getItem("titulky-lang"); } catch {}
let LANG = (() => {
  const q = new URLSearchParams(location.search).get("lang");
  for (const l of [q, savedLang, ...(navigator.languages || []), navigator.language]) {
    const c = String(l || "").slice(0, 2).toLowerCase();
    if (UI_LANGS[c]) return c;
    if (c === "cz") return "cs";
  }
  return "en";
})();
let LOCALE, LI;
const LANG_COL = { cs: 0, en: 1, es: 2, ar: 3, tr: 4, hi: 5, pl: 6, zh: 7 }; // stĺpec v slovníku
const setLangVars = () => { LOCALE = { sk: "sk-SK", cs: "cs-CZ", en: "en-GB", es: "es-ES", ar: "ar-AE", tr: "tr-TR", hi: "hi-IN", pl: "pl-PL", zh: "zh-CN" }[LANG]; LI = LANG_COL[LANG] ?? 1; document.documentElement.dir = LANG === "ar" ? "rtl" : "ltr"; };
setLangVars();
const decTxt = (v) => String(v).replace(".", ["sk", "cs", "es", "tr", "pl"].includes(LANG) ? "," : ".");
// Slovník: slovenský text → [čeština, angličtina, španielčina, arabčina, turečtina, hindčina, poľština, čínština]
