  "Skok": ["Skok","Bounce","Rebote","قفزة","Zıplama","उछाल","Podskok","弹跳"],
  "Písací stroj": ["Psací stroj","Typewriter","Máquina de escribir","آلة كاتبة","Daktilo","टाइपराइटर","Maszyna do pisania","打字机"],
  "Plynulé slová": ["Plynulá slova","Fade in","Aparición suave","ظهور تدريجي","Yumuşak giriş","फ़ेड इन","Płynne słowa","渐显文字"],
  "Vysunutie": ["Vysunutí","Slide up","Deslizar","انزلاق","Kayma","स्लाइड","Wysunięcie","上滑"],
